/*
J = P(α(F), β(L), S)
F ∈ ℝ
L ∈ ℝ
S ∈ ℝ
P ∈ ℝ, ℝ, ℝ -> ℝ


CFF(L) = a ⋅ log(L) + b where L ∈ ℝ

a ∈ ℝ
b ∈ ℝ


`$F_a$` = M⋅ CFF(`$L_a$`)

M ∈ ℝ
`$L_a$` ∈ ℝ

`$F_b$` = M⋅ CFF(`$L_b$`)

`$L_b$` ∈ ℝ

α(F) = 1/F where F ∈ ℝ

β(L) = log_10(L) where L ∈ ℝ

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT J;
    DT F_a;
    DT F_b;
    double L;
    double a;
    double b;
    double F;
    template<typename REAL>
    REAL CFF(
        const REAL & L)
    {
        return this->a * log(L) + this->b;    
    }
    template<typename REAL>
    REAL α(
        const REAL & F)
    {
        return 1 / REAL(F);    
    }
    template<typename REAL>
    REAL β(
        const REAL & L)
    {
        return log10(L);    
    }
    heartlib(
        const double & F,
        const double & L,
        const double & S,
        const std::function<double(double, double, double)> & P,
        const double & a,
        const double & b,
        const double & M,
        const double & L_a,
        const double & L_b)
    {

        this->L = L;
        this->a = a;
        this->b = b;
        this->F = F;
        // `$F_a$` = M⋅ CFF(`$L_a$`)
        F_a = M * CFF(L_a);
        // `$F_b$` = M⋅ CFF(`$L_b$`)
        F_b = M * CFF(L_b);
        // J = P(α(F), β(L), S)
        J = P(α(F), β(L), S);
    }
};

