function output = heartlib(F, L, S, P, a, b, M, L_a, L_b)
% output = heartlib(F, L, S, P, a, b, M, `$L_a$`, `$L_b$`)
%
%    J = P(α(F), β(L), S)
%    F ∈ ℝ
%    L ∈ ℝ
%    S ∈ ℝ
%    P ∈ ℝ, ℝ, ℝ -> ℝ
%    
%    
%    CFF(L) = a ⋅ log(L) + b where L ∈ ℝ
%    
%    a ∈ ℝ
%    b ∈ ℝ
%    
%    
%    `$F_a$` = M⋅ CFF(`$L_a$`)
%    
%    M ∈ ℝ
%    `$L_a$` ∈ ℝ
%    
%    `$F_b$` = M⋅ CFF(`$L_b$`)
%    
%    `$L_b$` ∈ ℝ
%    
%    α(F) = 1/F where F ∈ ℝ
%    
%    β(L) = log_10(L) where L ∈ ℝ
%    
    assert(numel(F) == 1);
    assert(numel(L) == 1);
    assert(numel(S) == 1);
    assert(numel(a) == 1);
    assert(numel(b) == 1);
    assert(numel(M) == 1);
    assert(numel(L_a) == 1);
    assert(numel(L_b) == 1);

    % `$F_a$` = M⋅ CFF(`$L_a$`)

    F_a = M * CFF(L_a);
    % `$F_b$` = M⋅ CFF(`$L_b$`)

    F_b = M * CFF(L_b);
    % J = P(α(F), β(L), S)

    J = P(alpha(F), beta(L), S);
    function [ret_1] = CFF(L)
        assert(numel(L) == 1);

        ret_1 = a * log(L) + b;
    end

    function [ret_2] = alpha(F)
        assert(numel(F) == 1);

        ret_2 = 1 / F;
    end

    function [ret_3] = beta(L)
        assert(numel(L) == 1);

        ret_3 = log10(L);
    end

    output.J = J;
    output.F_a = F_a;
    output.F_b = F_b;
    output.CFF = @CFF;
    output.alpha = @alpha;
    output.beta = @beta;
    output.L = L;    
    output.a = a;    
    output.b = b;    
    output.F = F;
end
